export function price(amount, qty) {
  return Math.round(amount * qty * 100) / 100;
}

export function discount(amount) {
  return Math.round(amount * 90) / 100;
}

A.checkout.js:
import { price, discount } from './pricing.js';

export function checkout(cart) {
  let total = 0;
  for (const line of cart) {
    total += price(line.amount, line.qty);
  }
  return discount(total);
}

